-- 해외 종목 표시명을 사용자 지정 한글명으로 통일한다.
UPDATE "TB_STK" SET "STK_NM"=CASE "STK_CD"
WHEN 'BOTZ' THEN 'BOTZ' WHEN 'HYDR' THEN 'HYDR' WHEN 'QQQ' THEN 'QQQ' WHEN 'SCHD' THEN 'SCHD' WHEN 'SMH' THEN 'SMH' WHEN 'SPY' THEN 'SPY' WHEN 'VIG' THEN 'VIG' WHEN 'XLF' THEN 'XLF' WHEN 'XLI' THEN 'XLI' WHEN 'XLV' THEN 'XLV'
WHEN 'GEV' THEN 'GE 버노바' WHEN 'MSFT' THEN '마이크로소프트' WHEN 'BAC' THEN '뱅크오브아메리카' WHEN 'BRK.B' THEN '버크셔 해서웨이 B' WHEN 'VRT' THEN '버티브 홀딩스' WHEN 'AVGO' THEN '브로드컴' WHEN 'VST' THEN '비스트라 에너지' WHEN 'V' THEN '비자' WHEN 'SPCX' THEN '스페이스X' WHEN 'ANET' THEN '아리스타 네트웍스' WHEN 'AMZN' THEN '아마존닷컴' WHEN 'IONQ' THEN '아이온큐' WHEN 'GOOGL' THEN '알파벳A' WHEN 'ABBV' THEN '애브비' WHEN 'AAPL' THEN '애플' WHEN 'NVDA' THEN '엔비디아' WHEN 'WMT' THEN '월마트' WHEN 'INTC' THEN '인텔' WHEN 'LLY' THEN '일라이 릴리' WHEN 'JPM' THEN '제이피모간체이스' WHEN 'JNJ' THEN '존슨앤드존슨' WHEN 'CAT' THEN '캐터필러' WHEN 'COST' THEN '코스트코 홀세일' WHEN 'CEG' THEN '콘스텔레이션 에너지' WHEN 'PLTR' THEN '팔란티어' WHEN 'PLUG' THEN '플러그파워' ELSE "STK_NM" END,
"UPD_DTTM"=CURRENT_TIMESTAMP,"UPD_USR_ID"='SYSTEM'
WHERE "MKT_CD"='US' AND "STK_CD" IN ('BOTZ','HYDR','QQQ','SCHD','SMH','SPY','VIG','XLF','XLI','XLV','GEV','MSFT','BAC','BRK.B','VRT','AVGO','VST','V','SPCX','ANET','AMZN','IONQ','GOOGL','ABBV','AAPL','NVDA','WMT','INTC','LLY','JPM','JNJ','CAT','COST','CEG','PLTR','PLUG');
